-- title:  game title
-- author: game developer
-- desc:   short description
-- script: lua
-- [resumo]
-- Backup do daviSystem 1 (versão um pouco mais antiga do daviSystem.lua).
-- ------------------------------------------------------------

joystick = false
scamx, scamy = 240, 136
cell = 8
rows, cols = scamx//cell, scamy//cell


imagems = {
	[0x0] = {name = "wallpaper", x = 0, y = 0},
}

workspace = {
	wallpaper = imagems[0x0],
	cell = 10,
	space = {}
}


function workspace.space:drawAPP()
	local cell = workspace.cell
	for k, app in ipairs(workspace.space) do
		app.workspace.x, app.workspace.y = 1+cell*((k//cell)%8), 1+((k//cell)//cell)*cell
		spr(
			app.icon,
			app.workspace.x+(cell/2),
			app.workspace.y,
			0
		)
		print(
			app.title:sub(1,4).."...",
			app.workspace.x,
			app.workspace.y+cell,
			12,
			false,
			1,
			true
		) 
	end
end

function workspace.space:functionAPP()
	local cell = workspace.cell
	for k, app in ipairs(workspace.space) do
		local mx, my, ml = mouse()
		for w = 0, cell do
			for h = 0, cell do
				if mx == app.workspace.x+w and my == app.workspace.y+h and ml == true then
					table.insert(windows, app)
				end
			end
		end
	end
end

function workspace:draw()
	map(
		workspace.wallpaper.x,
		workspace.wallpaper.y,
		rows,
		cols
	)
end

windows = {}
window = {x=0, y=0, w=scamx, h=scamy}
function windows:functionAPP()
	for k, app in ipairs(windows) do
		mx, my, ml = mouse_() 
		app.update(app)
		for w = 0, 8 do
			for h = 0, 8 do
				if app.win.w-w == mx and app.win.h-h == my and ml == true then
					table.remove(app, windows)
				elseif windows[k-1] == app then
					table.remove(windows, k) 
				end
			end 
		end  
		rect(app.win.x,app.win.y,app.win.w,app.win.h,12) 
		print(app.title,app.win.x+1,app.win.y+1)
		spr(2,app.win.x+app.win.w-8,0)
	end
end

apps = {}
function createAPP(APP, windows, icon)
	local backup={
		functionPrint=print
	}
	local app = {
		icon = icon or 256,
		scriptLoad = APP,
		workspace = {
			x = 0, y= 0
		},
		win = {
			x = windows.x or 0,
			y = windows.y or 0, 
			w = windows.w or scamx, 
			h = windows.h or scamy,
			titleH=8,
			print = function(s, str, x, y, color, fixed, scale, smallfont)
				backup.functionPrint(str, (x or 0)+s.x, (y or 0)+s.y, color, fixed, scale, smallfont)
			end,
			cls = function(s, color)
				rect(s.x, s.y, s.w, s.h, color)
			end
		},
	}
  
	app.update, app.title, app.author, app.desc, app.script=app.scriptLoad(app.win)
	table.insert(workspace.space, app)
end


taskbar = {
	color = 15,
	x = 0,
	y = ((scamy*0.99)//8)*8,
	w = scamx,
	space = {},
}
taskbar.h = ((scamy-taskbar.y)//8)*8

menu = {
	color = 15,
	x = 0,
	h = taskbar.y*0.5,
	w = scamx*0.5,
	visivel = false
}
menu.y = (taskbar.y)-menu.h

local m = {}
m.x, m.y, m.l, m.r = 0, 0, false, false
m.historico = {
	[0] = {
		x = m.x, 
		y = m.y,
		l = m.l,
		r = m.r
	}
}
function m:draw()
	spr(1 ,m.x ,m.y ,0)
end

function mouse_() 
	if joystick == false then
		m.x, m.y, m.l, m.r = mouse()
	elseif joystick == true then
		local vx, vy = 0, 0
		local spd = 0.7
	
		if btn(0) then vy=-spd end
		if btn(1) then vy=spd end
		if btn(2) then vx=-spd end
		if btn(3) then vx=spd end
   
		m.x=m.x+vx
		m.y=m.y+vy
   
		m.l = btn(4) or false
		m.r = btn(5) or false
	end
 
	if m.x < 0 then m.x=0 end
	if m.x > 240 then m.x=240 end 
	if m.y < 0 then m.y=0 end
	if m.y > 136 then m.y=136 end 
 
	m.historico[#m.historico+1] = {
		x=m.x,
		y=m.y,
		l=m.l,
		r=m.r
	}

	return m.x, m.y, m.l, m.r, m.historico[#m.historico-2]
end

function taskbar:draw()
	rect(
		taskbar.x,
		taskbar.y,
		taskbar.w,
		taskbar.h,
		taskbar.color
	)
 
	--apps
	local space=0
	for k,s in pairs(taskbar.space) do
		spr(
			s.sprite,
			taskbar.x+space,
			taskbar.y,
			s.clk
		)
		space=space+8
	end
 
	--date 
	date=tstamp()
	mindate=(date//60)
	min=mindate%60
	hourdate=((mindate)//60)-3	
	hour=hourdate%24
 
	print(
		hour..":"..min,
		taskbar.w*0.865,
		taskbar.y+2,
		12,
		false,
		1,
		true
	)
end

function taskbar:function_()
 
	local mx,my,l=mouse_(joystick)
 
	local space=0
	for k,s in pairs(taskbar.space) do
		local x=taskbar.x+space
		local y=taskbar.y
		local w=8
		local h=taskbar.h
 
		for w=0,w do
			for h=0,h do
				if x+w==mx and y+h==my and l==true then
					s.function_()
				end
			end
 
		end
		space=space+8
 
	end
end

function menu:create()
	taskbar.space["menu"] = {name="menu", sprite=0, clk=0, function_=menu.open}
end

function menu:open()
	menu.visivel = true
end

function menu:close()
	local mx, my, l, r, mhis = mouse_(joystick)
	local x, y, w, h = menu.x, menu.y, menu.w, menu.h
	if x+w < mx or y+h < my or x > mx or y > my then
		if l == true and mhis.l ~= l or mhis.r ~= r then
			menu.visivel = false
		end
	end
end

function menu:draw()
	local x, y, w, h = menu.x, menu.y, menu.w, menu.h
	if menu.visivel == true then
		rect(x, y, w, h, menu.color)
	end
end


createAPP(
	function (win)
		local posx,posy=win.x,win.y+win.h
		local resx,resy=240-posx,taskbar.y-posy
		local textDied=win:print("died")
		local textPress=win:print("press X to start over")
	
		local title,author,desc,script= "Skip Ahead","exoticorn", "256 byte game for lovebyte 2021","lua" 
  
		local p,px,py=0,2,0
		local s,f,spd,pspd=0,0,.03,1
		local death=false
		
		local function init()
			p,px,py=0,2,0
			s,f,spd=.0,.0,.03
			death=false
		end
		
		local function deathScreen()
			local size=2
			win:cls(12)
			win:print(
				"Died",
				(resx/2)-textDied,
				(resy/2),
				0,false,size
			)
			win:print(
				"press X to start over",
				(resx/2)-(textPress/2),
				(resy/1.5)
			)
		 if btn(5) then 
				init()
			end
		end
		
		init()
		function update(selfapp)
			win:cls(0)	
			win:print(p,3,3,3)
			for y=1,resx-2 do
				z=(200/y+p/20)//1
				x=z*200
				x=x~(x<<13)
				x=x~(x>>17)
				x=x~(x<<1)
				x=x~(x<<13)
				x=x~(x>>17)
				x=x~(x<<1)
				x=x~(x<<13)
				x=x~(x>>17)
				x=x~(x<<1)
				x=x~(x<<13)
				x=x~(x>>17)
				x=(x&3)/2-px
				w=6/z^0.5
				if resy>y+11 then rect((resx/2)+y*x,y,y*w,y/9,3+(z&1)) end
				if resy>y then  rect((resx/2)+y*x,y,y*w,1,5+(z&1)) end
				if y==(resx/2) and py>0 then
					if x+w<0 or x>0 then
						death=true
					end
					py=0
					s=0
					f=.8
				end
			end
			circ((resx/2),(resy/1.1982)+py,11,2)
			circ((resx/2)-3,(resy/1.1982)+py-3,3,3)
			p=p+pspd
			if btn(2) then px=px-spd end
			if btn(3) then	px=px+spd end		
			if btn(4) then s=s-f-spd end
			s=s+.1
			py=py+s
			f=f*.7		
			if death==true then
				deathScreen()
				pspd=0
			end
			if pspd==0 and death~=true then
				pspd=1			
			end
		end
		return update,title,author,desc,script
	end,
	windows
)

function create()
	menu:create()
end

function initSystem()

	FakeTIC=system
end

function system()

	taskbar:function_()
	menu:close()
 
	--draw
	workspace:draw()
	workspace.space:drawAPP()
	workspace.space:functionAPP()
 
	taskbar:draw()
 
	windows:functionAPP()
 
	m:draw()
	menu:draw()
end


FakeTIC = function() end
 
FakeTIC = initSystem
create() 
function TIC()

	FakeTIC()
end

